const fs = require('fs');
const path = require('path');

const README_PATH = path.join(__dirname, 'README.md');
const INDEX_PATH = path.join(__dirname, 'INDEX.md');

const headingPattern = /^#{1,6}\s+\S/;

function extractHeadings(markdown) {
  return markdown
    .split(/\r?\n/)
    .filter((line) => headingPattern.test(line));
}

function main() {
  const markdown = fs.readFileSync(README_PATH, 'utf8');
  const headings = extractHeadings(markdown);
  fs.writeFileSync(INDEX_PATH, headings.join('\n') + '\n', 'utf8');
  console.log(`Wrote ${headings.length} headings to ${path.basename(INDEX_PATH)}`);
}

main();

